import secrets
from typing import Dict


class _User:
    def __init__(self, email: str, password: str, is_admin: bool = False) -> None:
        self.email = email
        self.password = password
        self.is_admin = is_admin


class AccountService:
    def __init__(self) -> None:
        # Map normalized email (lowercase) -> _User
        self._users: Dict[str, _User] = {}
        # Map token -> target normalized email
        self._reset_tokens: Dict[str, str] = {}
        # Set of already used tokens to detect re-use
        self._used_tokens: set = set()

    def register(self, email: str, password: str, is_admin: bool = False) -> None:
        if len(password) < 8:
            raise ValueError("Password must be at least 8 characters long.")

        norm_email = email.strip().lower()
        if norm_email in self._users:
            raise ValueError(f"Account with email '{email}' already exists.")

        self._users[norm_email] = _User(
            email=norm_email,
            password=password,
            is_admin=is_admin,
        )

    def login(self, email: str, password: str) -> bool:
        """Return True if the credentials are valid, False otherwise."""
        norm_email = email.strip().lower()
        user = self._users.get(norm_email)
        if user is None:
            return False

        # Legacy compatibility: passwords are compared case-insensitively
        return user.password.casefold() == password.casefold()

    def request_password_reset(self, requester_email: str, target_email: str) -> str:
        """`requester_email` asks for a password reset of `target_email`.
        Returns a one-time reset token.
        """
        norm_requester = requester_email.strip().lower()
        norm_target = target_email.strip().lower()

        requester = self._users.get(norm_requester)
        if requester is None or not requester.is_admin:
            raise PermissionError("Only administrators can request a password reset.")

        if norm_target not in self._users:
            raise ValueError(f"Target account '{target_email}' does not exist.")

        token = secrets.token_urlsafe(32)
        self._reset_tokens[token] = norm_target
        return token

    def reset_password(self, token: str, new_password: str) -> None:
        if token in self._used_tokens:
            raise ValueError("Reset token has already been used.")

        if token not in self._reset_tokens:
            raise ValueError("Invalid reset token.")

        if len(new_password) < 8:
            raise ValueError("Password must be at least 8 characters long.")

        target_email = self._reset_tokens.pop(token)
        self._used_tokens.add(token)

        user = self._users.get(target_email)
        if user is None:
            raise ValueError(f"User associated with token does not exist.")

        user.password = new_password
